mapper.select:
SELECT R.PET_PRTC_RCRT_SN , R.PST_SN , P.PST_TTL , P.PST_CN , (SELECT I.ATCH_FILE_SN FROM PST_IMG I WHERE I.PST_SN = R.PST_SN AND I.DEL_YN = 'N' ORDER BY I.SORT_SEQ, I.PST_IMG_SN LIMIT 1) AS THUMBNAIL_ATCH_FILE_SN , M.MBR_NCNM , M.ATCH_FILE_SN AS MBR_ATCH_FILE_SN , R.RLS_RGN_NM , R.CST_UNIT_CD , R.CST_AMT , AS APLCNT_CNT , R.RCRT_STTS_CD , R.PRTC_BGNG_DT , R.PRTC_END_DT , (R.SCHDL_CNSLTN_PSBLTY_YN = 'Y') AS SCHDL_CNSLTN_PSBLTY_YN , P.REG_DT , (P.MBR_SN = #{mbrSn}) AS OWNER_YN FROM PET_PRTC_RCRT R JOIN PST P ON P.PST_SN = R.PST_SN JOIN MBR M ON M.MBR_SN = P.MBR_SN WHERE P.PST_STTS_CD = #{pstSttsCd}
AND R.RCRT_STTS_CD = #{rcrtSttsCd}
AND P.MBR_SN = #{mbrSn}
AND R.RGN_SN IN (WITH RECURSIVE T AS (SELECT RGN_SN FROM RGN WHERE RGN_SN = #{rgnSn} UNION ALL SELECT C.RGN_SN FROM RGN C JOIN T ON C.UP_RGN_SN = T.RGN_SN) SELECT RGN_SN FROM T)
AND R.PRTC_BGNG_DT IS NOT NULL AND R.PRTC_END_DT IS NOT NULL
AND R.PRTC_END_DT >= #{bgngDt}
AND R.PRTC_BGNG_DT < #{endDt}
AND EXISTS (SELECT 1 FROM RCRT_PET_KND K WHERE K.PET_PRTC_RCRT_SN = R.PET_PRTC_RCRT_SN AND K.PET_SE_CD = #{petSeCd})
AND EXISTS (SELECT 1 FROM RCRT_PET_KND K WHERE K.PET_PRTC_RCRT_SN = R.PET_PRTC_RCRT_SN AND K.PET_SE_CD = #{dogCd} AND K.PET_BDWG >= #{minBdwg}
AND K.PET_BDWG < #{maxBdwg}
)
ORDER BY P.REG_DT DESC , R.PET_PRTC_RCRT_SN DESC

SELECT EXISTS (SELECT 1
                 FROM OTO_CHAT_ROOM C
                 JOIN CHAT_PRTPNT T
                   ON T.OTO_CHAT_ROOM_SN = C.OTO_CHAT_ROOM_SN
                  AND T.MBR_SN = #{mbrSn}
                  AND T.PTCP_STTS_CD = #{joinedCd}
                WHERE C.PST_SN = #{pstSn}
                  AND EXISTS (SELECT 1
                                FROM CHAT_MSG G
                               WHERE G.OTO_CHAT_ROOM_SN = C.OTO_CHAT_ROOM_SN))

SELECT K.RCRT_PET_KND_SN , K.PET_PRTC_RCRT_SN , K.PET_SE_CD , K.PET_BDWG , K.VRTY_SN , K.VRTY_DRCT_INPT_NM , K.REG_DT , V.VRTY_NM FROM RCRT_PET_KND K LEFT JOIN VRTY V ON V.VRTY_SN = K.VRTY_SN WHERE K.PET_PRTC_RCRT_SN IN
#{sn}
ORDER BY K.PET_PRTC_RCRT_SN , K.RCRT_PET_KND_SN

SELECT S.RCRT_PRTC_SHP_SN , S.PET_PRTC_RCRT_SN , S.PRTC_SHP_CD , S.REG_DT FROM RCRT_PRTC_SHP S WHERE S.PET_PRTC_RCRT_SN IN
#{sn}
ORDER BY S.PET_PRTC_RCRT_SN , S.PRTC_SHP_CD

SELECT 
 WHERE P.PST_STTS_CD = #{pstSttsCd}

   AND R.RCRT_STTS_CD = #{rcrtSttsCd}

 ORDER BY P.REG_DT DESC
        , R.PET_PRTC_RCRT_SN DESC

mapper.insert:
INSERT INTO PET_PRTC_RCRT
     ( PST_SN
     , RGN_SN
     , RCRT_STTS_CD
     , CST_UNIT_CD
     , CST_AMT
     , RLS_RGN_NM
     , PRTC_PLC_DADDR_ENC
     , PRTC_BGNG_DT
     , PRTC_END_DT
     , SCHDL_CNSLTN_PSBLTY_YN
     , UTZTN_RUL_AGRE_YN
     , PRTC_PLC_LAT
     , PRTC_PLC_LOT
     , REG_DT
     , MDFCN_DT )
VALUES
     ( #{pstSn}
     , #{rgnSn}
     , #{rcrtSttsCd}
     , #{cstUnitCd}
     , #{cstAmt}
     , #{rlsRgnNm}
     , #{prtcPlcDaddrEnc}
     , #{prtcBgngDt}
     , #{prtcEndDt}
     , #{schdlCnsltnPsbltyYn}
     , #{utztnRulAgreYn}
     , #{prtcPlcLat}
     , #{prtcPlcLot}
     , NOW()
     , NOW() )

INSERT INTO RCRT_PET_KND
     ( PET_PRTC_RCRT_SN
     , PET_SE_CD
     , PET_BDWG
     , VRTY_SN
     , VRTY_DRCT_INPT_NM
     , REG_DT )
VALUES
     ( #{petPrtcRcrtSn}
     , #{petSeCd}
     , #{petBdwg}
     , #{vrtySn}
     , #{vrtyDrctInptNm}
     , NOW() )

INSERT INTO PET_PRTC_RCRT_STTS_HSTRY
     ( PET_PRTC_RCRT_SN
     , MBR_SN
     , BFR_STTS_CD
     , AFTR_STTS_CD
     , CHG_RSN
     , REG_DT )
VALUES
     ( #{petPrtcRcrtSn}
     , #{mbrSn}
     , #{bfrSttsCd}
     , #{aftrSttsCd}
     , #{chgRsn}
     , NOW() )

mapper.update:
UPDATE PET_PRTC_RCRT
   SET RGN_SN = #{recruitment.rgnSn}
     , CST_UNIT_CD = #{recruitment.cstUnitCd}
     , CST_AMT = #{recruitment.cstAmt}
     , RLS_RGN_NM = #{recruitment.rlsRgnNm}
     , PRTC_PLC_DADDR_ENC = #{recruitment.prtcPlcDaddrEnc}
     , PRTC_BGNG_DT = #{recruitment.prtcBgngDt}
     , PRTC_END_DT = #{recruitment.prtcEndDt}
     , SCHDL_CNSLTN_PSBLTY_YN = #{recruitment.schdlCnsltnPsbltyYn}
     , PRTC_PLC_LAT = #{recruitment.prtcPlcLat}
     , PRTC_PLC_LOT = #{recruitment.prtcPlcLot}
     , MDFCN_DT = NOW()
 WHERE PET_PRTC_RCRT_SN = #{recruitment.petPrtcRcrtSn}
   AND RCRT_STTS_CD = #{recruitingCd}

UPDATE PET_PRTC_RCRT
   SET RCRT_STTS_CD = #{aftrSttsCd}
     , CFMTN_PET_PRTC_MTCH_SN = #{cfmtnPetPrtcMtchSn}
     , MDFCN_DT = NOW()
 WHERE PET_PRTC_RCRT_SN = #{petPrtcRcrtSn}
   AND RCRT_STTS_CD = #{bfrSttsCd}
